using System.Security.Claims;
using System.Text.Json;
using EduForge.Domain;
using EduForge.Infrastructure;
using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;
public record ReviewDecision(bool Approve,string Reason);
public static class ModerationEndpoints {
 public static async Task<IResult> Queue(MaterialDbContext db,Guid owner,Guid source,string kind,string title,string payload,CancellationToken ct){db.ChangeTracker.Clear();await using var tx=await db.Database.BeginTransactionAsync(ct);await db.PublicationReviews.Where(x=>x.SourceId==source&&x.Kind==kind&&x.Status=="Pending").ExecuteUpdateAsync(s=>s.SetProperty(x=>x.Status,"Superseded"),ct);db.PublicationReviews.Add(new PublicationReview{TeacherId=owner,SourceId=source,Kind=kind,Title=title,Payload=payload});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.Ok(new{Published=false,Status="Pending",PublishedAt=(long?)null});}
 public static void MapModeration(this WebApplication app){var routes=app.MapGroup("/api/moderation").RequireAuthorization();routes.AddEndpointFilter(async(context,next)=>{var db=context.HttpContext.RequestServices.GetRequiredService<MaterialDbContext>();var id=Guid.Parse(context.HttpContext.User.FindFirstValue(ClaimTypes.NameIdentifier)!);var t=await db.Teachers.SingleAsync(x=>x.Id==id);return AdminEndpoints.IsAdmin(t.Email,app.Configuration)?await next(context):Results.Forbid();});
 routes.MapGet("/",async(MaterialDbContext db,CancellationToken ct)=>Results.Ok(await db.PublicationReviews.Where(x=>x.Status=="Pending").OrderBy(x=>x.CreatedAt).ToListAsync(ct)));
 routes.MapPost("/{id:guid}",async(Guid id,ReviewDecision input,MaterialDbContext db,CancellationToken ct)=>{if(input.Reason is null||input.Reason.Length>2000||!input.Approve&&string.IsNullOrWhiteSpace(input.Reason))return Results.BadRequest();await using var tx=await db.Database.BeginTransactionAsync(ct);var review=await db.PublicationReviews.SingleOrDefaultAsync(x=>x.Id==id&&x.Status=="Pending",ct);if(review is null)return Results.NotFound();var claimed=await db.PublicationReviews.Where(x=>x.Id==id&&x.Status=="Pending").ExecuteUpdateAsync(s=>s.SetProperty(x=>x.Status,"Processing"),ct);if(claimed==0)return Results.Conflict();var newer=await db.PublicationReviews.AnyAsync(x=>x.SourceId==review.SourceId&&x.Kind==review.Kind&&x.CreatedAt>review.CreatedAt,ct);if(newer)return Results.Conflict(new{message="Есть более новая версия заявки. Рассмотрите её."});if(input.Approve){
 var access=await db.ContentAccesses.SingleOrDefaultAsync(a=>a.SourceId==review.SourceId&&a.Kind==review.Kind,ct);
 if(access is not null){using var payload=JsonDocument.Parse(review.Payload);var valid=payload.RootElement.TryGetProperty("AccessVersion",out var version)&&Guid.TryParse(version.GetString(),out var expected)&&expected==access.Version&&access.Visibility=="Public";if(!valid)return Results.Conflict(new{message="Автор изменил доступ. Эта заявка больше не действует."});db.Entry(access).Property(a=>a.Version).IsModified=true;}
 if(review.Kind=="material"){if(!await db.Materials.AnyAsync(x=>x.Id==review.SourceId&&x.TeacherId==review.TeacherId,ct))return Results.NotFound();var snapshot=JsonSerializer.Deserialize<PublishedMaterial>(review.Payload)!;var old=await db.Publications.SingleOrDefaultAsync(x=>x.Id==review.SourceId,ct);if(old is null)db.Publications.Add(snapshot);else db.Entry(old).CurrentValues.SetValues(snapshot);}else{if(!await db.Quizzes.AnyAsync(x=>x.Id==review.SourceId&&x.TeacherId==review.TeacherId,ct))return Results.NotFound();var snapshot=JsonSerializer.Deserialize<PublishedQuiz>(review.Payload)!;var old=await db.QuizPublications.SingleOrDefaultAsync(x=>x.Id==review.SourceId,ct);if(old is null)db.QuizPublications.Add(snapshot);else db.Entry(old).CurrentValues.SetValues(snapshot);}}review.Status=input.Approve?"Approved":"Rejected";review.Reason=input.Reason.Trim();try{await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}catch(DbUpdateConcurrencyException){return Results.Conflict(new{message="Настройки доступа изменились во время модерации. Обновите очередь."});}return Results.NoContent();});
 }
}
